 const round=(mini=false,three=false)=> <>{h(36,23)}{v(90,23)}<circle cx="90" cy="36" r={mini?29:35} fill={roadColor} stroke={ink} strokeWidth="0.9"/><circle cx="90" cy="36" r={mini?15:21} fill={bg} stroke={ink} strokeWidth="0.9"/><circle cx="90" cy="36" r={mini?22:28} fill="none" stroke={lane} strokeDasharray="3 4" strokeWidth="0.8"/>{three&&<rect x="77" y="84" width="26" height="18" fill={bg}/>} {dash('M -20 36 H 49')}{dash('M 131 36 H 200')}{dash('M 90 -20 V -4')}{!three&&dash('M 90 77 V 120')}</>;
 const island=()=> <>{shape('M -20 38 H 54 C 68 38 79 23 79 -20 H 101 C 101 23 112 38 126 38 H 200 V 62 H 126 C 112 62 101 77 101 120 H 79 C 79 77 68 62 54 62 H -20 Z')}{shape('M 67 38 L 79 26 V 38 Z')}{shape('M 101 26 L 113 38 H 101 Z')}{shape('M 67 62 H 79 V 74 Z')}{shape('M 101 62 H 113 L 101 74 Z')}{dash('M -20 50 H 65')}{dash('M 115 50 H 200')}{dash('M 90 -20 V 26')}{dash('M 90 74 V 120')}</>;
